def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))

    def try_axis(axis):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        lines = []
        for i in range(n):
            vals = [grid[i][j] if axis == 0 else grid[j][i] for j in range(m)]
            if len(set(vals)) == 1 and vals[0] != bg:
                lines.append((i, vals[0]))
        if not lines:
            return None
        # Treat repeated monochrome lines as separators of equal-sized tiles.
        sep = [i for i, _ in lines]
        bounds = [-1] + sep + [n]
        chunks = [(bounds[k]+1, bounds[k+1]) for k in range(len(bounds)-1)]
        sizes = [b-a for a,b in chunks]
        size = max(sizes)
        if size == 0:
            return None
        # Merge all tile contents by position, letting the first non-background value win.
        pattern = [[bg for _ in range(m)] for _ in range(size)]
        for a,b in chunks:
            for pos in range(b-a):
                for j in range(m):
                    v = grid[a+pos][j] if axis == 0 else grid[j][a+pos]
                    if v != bg and pattern[pos][j] == bg:
                        pattern[pos][j] = v
        out = [row[:] for row in grid]
        for a,b in chunks:
            for pos in range(b-a):
                for j in range(m):
                    v = pattern[pos][j]
                    if axis == 0:
                        out[a+pos][j] = v
                    else:
                        out[j][a+pos] = v
        return out

    # The task's separator is a complete uniform row or column.
    row_result = try_axis(0)
    col_result = try_axis(1)
    if row_result is not None and col_result is None:
        return row_result
    if col_result is not None and row_result is None:
        return col_result
    if row_result is not None:
        # Prefer the orientation with more separator lines.
        nr = sum(len(set(r)) == 1 and r[0] != bg for r in grid)
        nc = sum(len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg for c in range(w))
        return row_result if nr >= nc else col_result
    return [row[:] for row in grid]

